const count = ref(0)
count.value++

const state = reactive({ count: 0 })
state.count++

Une ref qui reçoit un objet le rend lui-même profondément réactif (via reactive()), donc ref() couvre aussi les objets.

Pseudo-code de la page :

function reactive(obj) {
  return new Proxy(obj, {
    get(target, key) {
      track(target, key)
      return target[key]
    },
    set(target, key, value) {
      target[key] = value
      trigger(target, key)
    }
  })
}

function ref(value) {
  const refObject = {
    get value() {
      track(refObject, 'value')
      return value
    },
    set value(newValue) {
      value = newValue
      trigger(refObject, 'value')
    }
  }
  return refObject
}

La réactivité de Vue est runtime (faite à l'exécution dans le navigateur), contrairement à une approche compile-time comme Svelte.

