Options :
- immediate: true : callback des la creation (oldValue undefined)
- deep: true (3.5+ : un nombre = profondeur max)
- once: true (3.4+) : un seul declenchement puis arret

import { watch, onWatcherCleanup } from 'vue'

watch(id, (newId) => {
  const controller = new AbortController()

  fetch(`/api/${newId}`, { signal: controller.signal }).then(() => {
    // callback logic
  })

  onWatcherCleanup(() => {
    controller.abort() // abort stale request
  })
})

// alternative
watch(id, (newId, oldId, onCleanup) => {
  onCleanup(() => { /* cleanup */ })
})

// arrete automatiquement
watchEffect(() => {})

// ...pas celui-ci !
setTimeout(() => {
  watchEffect(() => {})
}, 100)

const unwatch = watchEffect(() => {})
unwatch()

// 3.5+ : le handle expose aussi pause(), resume() et stop()

// recommande
watchEffect(() => {
  if (data.value) {
    // do something when data is loaded
  }
})

