// keys.ts
import type { InjectionKey, Ref } from 'vue'
export const countKey = Symbol() as InjectionKey<{ count: Readonly<Ref<number>>; inc: () => void }>

// Provider
const count = ref(0)
provide(countKey, { count: readonly(count), inc: () => count.value++ })

// Descendant
const { count, inc } = inject(countKey)!

InjectionKey type la valeur entre provider et consumer ; avec une clé string, inject renvoie unknown et il faut inject<string>('foo'). Le résultat peut être undefined sauf si on donne une valeur par défaut (voir https://vuejs.org/guide/typescript/composition-api.html#typing-provide-inject).

// Child.vue corrigé
const count = ref(1)
function reset() { count.value = 0 }
defineExpose({ count, reset })

useTemplateRef existe depuis 3.5 ; avant, on déclarait const child = ref(null) avec le même nom que l'attribut ref. En Options API, l'équivalent est l'option expose: ['publicData', 'publicMethod'].

